// Turfton FM on the air: the subtitle pill on screen, the music (generated by @lawn/music, one theme per station) and the
// timing of the programme. The rules are in schedule.ts and the words and songs in content.ts. The dial is remembered per
// browser (localStorage, so a blocked store just means it starts on The Blade). Nothing about the radio is synced online.
import { buildBlackjackJazz, buildGardenLullaby, buildTrickyTrack, playSong, setMuteKey, setSongMuffled, stopSong, type SongBuilder } from '@lawn/music';
import { EVENT_BULLETINS, STATIONS, type MusicTheme, type StationId } from './content';
import { createProgram, type Segment } from './schedule';

const DIAL_KEY = 'gta.radio';
/** The same key audio.ts uses for the M (mute) toggle, so one press silences the sound effects and the radio. */
const MUTE_KEY = 'gta.muted';
const DEFAULT_STATION: StationId = 'blade';
/** News that arrives while a bulletin is on air waits behind it, up to this many. */
const QUEUE_MAX = 3;
/** Event news about what the player did, kept while nobody is driving, up to this many. */
const PENDING_MAX = 2;

export interface RadioHooks {
  /** The player has heard a song on all three stations during one drive. */
  onFullDial?(): void;
  /** An event bulletin (about something the player did) went out on the air. Gets the achievement id. */
  onEventBulletin?(key: string): void;
}

export interface Radio {
  /** The tuned station, or null when the radio is off. */
  readonly station: StationId | null;
  /** Turn the dial one step. */
  cycle(): void;
  /** The player got into a vehicle: start the programme on the tuned station (event news kept from before goes out first). */
  start(): void;
  /** The player got out (or was cracked): silence and hide the pill. */
  stop(): void;
  /**
   * A Hat Watch level ("heat-1".."heat-3") or an achievement id went out as news. Heat news is only for a driver; event news
   * waits for the next drive. News that arrives while a bulletin is on air waits behind it.
   */
  news(key: string): void;
  /** Advance the programme by a frame. */
  update(dt: number): void;
}

const BUILD: Record<MusicTheme, (seed: number) => SongBuilder> = {
  'big-beat': (seed) => (T, keep, out) => buildTrickyTrack(T, keep, out, seed),
  lullaby: (seed) => (T, keep, out) => buildGardenLullaby(T, keep, out, seed),
  jazz: (seed) => (T, keep, out) => buildBlackjackJazz(T, keep, out, seed),
};

function loadDial(): StationId | null {
  try {
    const v = localStorage.getItem(DIAL_KEY);
    if (v === 'off') return null;
    if (v && STATIONS.some((s) => s.id === v)) return v as StationId;
  } catch {
    /* storage blocked: start on the default station */
  }
  return DEFAULT_STATION;
}

function saveDial(id: StationId | null): void {
  try {
    localStorage.setItem(DIAL_KEY, id ?? 'off');
  } catch {
    /* per-session only */
  }
}

const CSS = `
#gta-radio{position:fixed;left:calc(env(safe-area-inset-left) + 16px);right:calc(env(safe-area-inset-right) + 16px);
  bottom:calc(env(safe-area-inset-bottom) + 14px);text-align:center;pointer-events:none;}
#gta-radio .gr-box{display:inline-block;box-sizing:border-box;max-width:min(440px,100%);padding:7px 12px;border-radius:12px;
  background:rgba(16,16,16,.66);color:#fff;font:600 12px/1.35 system-ui,sans-serif;text-align:center;}
#gta-radio .gr-head{display:flex;gap:10px;justify-content:center;align-items:baseline;font-size:11px;letter-spacing:.06em;text-transform:uppercase;opacity:.9;white-space:nowrap;}
#gta-radio .gr-dial{font-weight:800;color:#ffd23f;}
#gta-radio .gr-hint{opacity:.7;}
#gta-radio .gr-line{margin-top:3px;font-size:13px;font-weight:600;}
#gta-radio .gr-who{margin-right:6px;color:#7cf0ff;font-weight:800;}
#gta-radio .gr-who.gr-talk{color:#ffd23f;}
#gta-radio .gr-who.gr-bulletin{color:#ff8a80;}
/* Phones in portrait: the touch buttons fill the bottom corners and the toasts sit at the top, so the pill goes on the
   left, under the toasts. */
@media (max-width:700px){
  #gta-radio{top:calc(env(safe-area-inset-top) + 270px);bottom:auto;text-align:left;}
  #gta-radio .gr-box{max-width:min(300px,76vw);text-align:left;}
  #gta-radio .gr-head{justify-content:flex-start;}
}
/* Phones in landscape (the HUD's short-screen layout): the vehicle readout and the touch buttons take the bottom, so the
   pill sits in the open middle, under the biome name. */
@media (max-height:500px){
  #gta-radio{top:calc(env(safe-area-inset-top) + 120px);bottom:auto;text-align:center;}
  #gta-radio .gr-box{max-width:min(300px,60vw);text-align:center;}
  #gta-radio .gr-head{justify-content:center;}
}
`;

export function createRadio(ui: HTMLElement, hooks: RadioHooks = {}): Radio {
  // The music's own mute reads the same key as the game's M toggle (see audio.ts).
  setMuteKey(MUTE_KEY);

  if (!document.getElementById('gta-radio-css')) {
    const style = document.createElement('style');
    style.id = 'gta-radio-css';
    style.textContent = CSS;
    document.head.appendChild(style);
  }
  const root = document.createElement('div');
  root.id = 'gta-radio';
  root.setAttribute('aria-live', 'polite');
  root.style.display = 'none';
  const head = document.createElement('div');
  head.className = 'gr-head';
  const dial = document.createElement('span');
  dial.className = 'gr-dial';
  const hint = document.createElement('span');
  hint.className = 'gr-hint';
  head.append(dial, hint);
  const line = document.createElement('div');
  line.className = 'gr-line';
  const who = document.createElement('b');
  who.className = 'gr-who';
  const text = document.createElement('span');
  line.append(who, text);
  const box = document.createElement('div');
  box.className = 'gr-box';
  box.append(head, line);
  root.append(box);
  ui.appendChild(root);

  const program = createProgram();
  program.tune(loadDial());

  let current: Segment | null = null;
  let remaining = 0;
  let inVehicle = false;
  let heard = new Set<StationId>();
  let fullDialSent = false;
  /** Event news that happened with nobody driving, kept until the next drive (oldest first). */
  const pending: string[] = [];
  /** News that arrived while a bulletin was on air (oldest first). */
  const queued: string[] = [];

  const stationOf = (id: StationId): (typeof STATIONS)[number] => STATIONS.find((s) => s.id === id)!;

  function render(): void {
    root.style.display = inVehicle ? '' : 'none';
    const id = program.station;
    dial.textContent = id ? `${stationOf(id).freq} ${stationOf(id).label}` : 'Radio off';
    hint.textContent = 'N: next station';
    if (!current) {
      who.textContent = '';
      who.className = 'gr-who';
      text.textContent = id ? '' : 'Tune in with N.';
      return;
    }
    if (current.kind === 'song') {
      who.textContent = 'Now playing';
      who.className = 'gr-who';
    } else {
      who.textContent = current.who;
      who.className = `gr-who ${current.kind === 'bulletin' ? 'gr-bulletin' : 'gr-talk'}`;
    }
    text.textContent = current.text;
  }

  function show(seg: Segment): void {
    current = seg;
    remaining = seg.seconds;
    if (seg.kind === 'song' && seg.song) {
      playSong(BUILD[stationOf(seg.station).theme](seg.song.seed));
      setSongMuffled(false);
      heard.add(seg.station);
      if (!fullDialSent && heard.size === STATIONS.length) {
        fullDialSent = true;
        hooks.onFullDial?.();
      }
    } else {
      // Talk and bulletins sit on top of whatever is playing, so the music drops back under them.
      setSongMuffled(true);
    }
    render();
  }

  /** Put an event or heat bulletin on air now. False when it has no lines or the radio is off. */
  function playBulletin(key: string): boolean {
    const seg = program.bulletin(key);
    if (!seg) return false;
    show(seg);
    if (!key.startsWith('heat-')) hooks.onEventBulletin?.(key);
    return true;
  }

  /** Keep event news for the next drive. Heat news is only for a driver, and an event with no bulletin is not kept at all. */
  function keepPending(key: string): void {
    if (key.startsWith('heat-') || !EVENT_BULLETINS[key]) return;
    pending.push(key);
    if (pending.length > PENDING_MAX) pending.shift();
  }

  function advance(): void {
    // A bulletin that was waiting behind the one that just ended goes out first.
    while (queued.length) {
      if (playBulletin(queued.shift()!)) return;
    }
    const seg = program.next();
    if (!seg) {
      current = null;
      stopSong();
      render();
      return;
    }
    show(seg);
  }

  const news = (key: string): void => {
    if (!inVehicle) {
      keepPending(key);
      return;
    }
    if (!program.station) return;
    if (current?.kind === 'bulletin') {
      // Heat rising during a bulletin about something the player just did must not cut it off: it waits its turn.
      if (queued.length < QUEUE_MAX) queued.push(key);
      return;
    }
    playBulletin(key);
  };

  return {
    get station() { return program.station; },
    cycle() {
      program.cycle();
      saveDial(program.station);
      current = null;
      queued.length = 0;
      stopSong();
      if (inVehicle) advance();
      else render();
    },
    start() {
      inVehicle = true;
      heard = new Set();
      fullDialSent = false;
      current = null;
      const key = pending.shift();
      if (key) news(key);
      if (!current) advance();
    },
    stop() {
      inVehicle = false;
      current = null;
      // Whatever was waiting to go out is still news: event news is kept for the next drive, heat news is dropped.
      for (const key of queued.splice(0)) keepPending(key);
      stopSong();
      render();
    },
    news,
    update(dt) {
      if (!inVehicle || !current) return;
      remaining -= dt;
      if (remaining <= 0) advance();
    },
  };
}
